# Maps the library's activesettings.activemode integer to a HVAC mode.
ACTIVE_MODE_TO_HVAC: dict[int, HVACMode] = {
    0: HVACMode.OFF,
    1: HVACMode.HEAT_COOL,
    2: HVACMode.COOL,
    3: HVACMode.HEAT,
    4: HVACMode.HEAT,  # E-Heat also maps to heating
}

# Maps a HVAC mode back to the integer expected by client.set_mode().
HVAC_TO_ACTIVE_MODE: dict[HVACMode, int] = {
    HVACMode.OFF: 0,
    HVACMode.HEAT_COOL: 1,
    HVACMode.COOL: 2,
    HVACMode.HEAT: 3,
}

# Maps the library's modeofoperation integer to the current HVAC action.
MODE_OF_OPERATION_TO_ACTION: dict[int, HVACAction] = {
    0: HVACAction.IDLE,
    1: HVACAction.FAN,
    2: HVACAction.COOLING,
    3: HVACAction.COOLING,
    4: HVACAction.HEATING,
    5: HVACAction.HEATING,
    6: HVACAction.HEATING,
    7: HVACAction.HEATING,
    8: HVACAction.HEATING,
    9: HVACAction.OFF,
}


def _fahrenheit_to_celsius(value: float | None) -> float | None:
    """Convert a Fahrenheit setpoint to Celsius, preserving None."""
    if value is None:
        return None
    return TemperatureConverter.convert(
        value, UnitOfTemperature.FAHRENHEIT, UnitOfTemperature.CELSIUS
    )


def _celsius_to_fahrenheit(value: float) -> float:
    """Convert a Celsius setpoint to Fahrenheit."""
    return TemperatureConverter.convert(
        value, UnitOfTemperature.CELSIUS, UnitOfTemperature.FAHRENHEIT
    )


async def async_setup_entry(
    hass: HomeAssistant,
    config_entry: WaterFurnaceConfigEntry,
    async_add_entities: AddConfigEntryEntitiesCallback,
) -> None:
    """Set up the WaterFurnace climate platform from a config entry."""
    async_add_entities(
        WaterFurnaceClimate(device_data.realtime)
        for device_data in config_entry.runtime_data.values()
    )


